<script setup lang="ts">
import {ref} from 'vue'
import type {Home} from '../types'
import type {StorageApi} from '../api'
import StorageReceiptSummary from '../StorageReceiptSummary.vue'
import StorageFollowupForm from '../StorageFollowupForm.vue'
import {displayName} from '../../shared-commerce/format'
import {dateTime,storageLocationText} from '../format'
import {useMerchantStorageText} from './text'
defineProps<{home:Home;api:StorageApi;disabled:boolean;canCorrect:boolean;canPhoto:boolean}>()
const emit=defineEmits<{command:[()=>Promise<unknown>];error:[unknown];changed:[]}>(),correction=ref({itemId:'',reason:'',note:''})
const {t,locale}=useMerchantStorageText(),section=ref('requests')
</script>
<template><section class="storage-section"><nav><button v-for="value in ['requests','collections','holdings','activity']" :key="value" :aria-pressed="section===value" :class="{primary:section===value}" @click="section=value">{{t(value)}}</button></nav>
 <template v-if="section==='requests'"><p v-if="!home.applications.length" class="storage-panel storage-empty">{{t('empty')}}</p><article v-for="a in home.applications" :key="a.id" class="storage-panel"><span class="cards-badge">{{t(a.status)}}</span><span v-if="home.events.some(e=>e.sourceId===a.id&&e.action==='staff.registered')" class="cards-badge">{{t('staff.registered')}}</span><p>{{dateTime(a.createdAt,home.timezone)}}</p><p v-for="line in a.lines" :key="line.id">{{displayName(line,locale)}} × {{line.quantity}} {{t('unit')}}</p><StorageReceiptSummary :application="a"/><p>{{a.reason}}</p><p v-if="home.items.find(item=>item.applicationId===a.id)?.snapshot.custodian">{{home.items.find(item=>item.applicationId===a.id)!.snapshot.custodian!.name}}</p><details v-if="a.confirmation"><summary>{{t('confirmed')}}</summary><p>{{a.confirmation.reason}}</p><p v-for="(line,index) in a.confirmation.lines" :key="index">{{line.nameZh||line.nameEn||a.lines.find(original=>original.id===line.lineId)?.nameZh}} × {{line.quantity}} · {{storageLocationText(line)}} · {{line.label}}</p></details></article></template>
 <template v-if="section==='collections'"><p v-if="!home.intents.length" class="storage-panel storage-empty">{{t('empty')}}</p><article v-for="intent in home.intents" :key="intent.id" class="storage-panel"><strong>{{t(intent.status)}}</strong><p>{{dateTime(intent.completedAt??intent.expiresAt,home.timezone)}}</p><p v-for="line in intent.selections" :key="line.itemId">{{home.items.find(i=>i.id===line.itemId)?displayName(home.items.find(i=>i.id===line.itemId)!.snapshot,locale):t('items')}} × {{line.quantity}} {{t('unit')}}</p></article></template>
 <template v-if="section==='holdings'"><p v-if="!home.items.length" class="storage-panel storage-empty">{{t('empty')}}</p><article v-for="item in home.items" :key="item.id" class="storage-panel"><h3>{{displayName(item.snapshot,locale)}}</h3><span class="cards-badge">{{t(item.status)}}</span><p>{{t('remaining')}} {{item.remaining}} / {{item.quantity}} {{t('unit')}}</p><p v-if="item.snapshot.custodian">{{t('custodianOptional')}}：{{item.snapshot.custodian.name}} · {{t(item.snapshot.custodian.kind)}}</p><p>{{t('location')}} {{storageLocationText(item)}} · {{t('label')}} {{item.label}}</p><small>{{t('expiresAt')}} {{dateTime(item.expiresAt,item.snapshot.timezone)}}</small><details><summary>{{t('photoPhase')}}</summary><div class="storage-photos"><img v-for="photo in [...item.snapshot.applicationPhotos,...item.snapshot.receiptPhotos]" :key="photo" :src="`${api.base}/photos/${photo}`" :alt="t('photos')"></div></details><button v-if="canCorrect" :disabled="disabled" @click="correction={itemId:item.id,reason:'',note:''}">{{t('correction')}}</button><StorageFollowupForm v-if="canPhoto" :api="api" :item="item" :disabled="disabled" @saved="emit('changed')" @error="emit('error',$event)"/></article><form v-if="correction.itemId" class="storage-panel" @submit.prevent="emit('command',async()=>{await api.command(`/items/${correction.itemId}/corrections`,correction);correction.itemId=''})"><p>{{t('correctHint')}}</p><label>{{t('reason')}}<input v-model="correction.reason" required maxlength="2000" :disabled="disabled"></label><label>{{t('note')}}<textarea v-model="correction.note" required maxlength="2000" :disabled="disabled"/></label><button :disabled="disabled||!correction.reason.trim()||!correction.note.trim()">{{t('confirm')}}</button></form></template>
 <template v-if="section==='activity'"><p v-if="!home.events.length" class="storage-panel storage-empty">{{t('empty')}}</p><article v-for="event in home.events" :key="event.id" class="storage-panel"><strong>{{t(event.action)}}</strong><p>{{dateTime(event.createdAt,home.timezone)}}</p><p v-if="event.details.reason">{{event.details.reason}}</p><p v-if="event.details.note">{{event.details.note}}</p><small>{{t('author')}} {{event.actorName?.trim()||t('unknownActor')}}</small></article></template>
</section></template>
